using MediatR;
using NetCalendy.Application.Common;
using NetCalendy.Domain.Common;
using NetCalendy.Domain.EventTypes;
using NetCalendy.Domain.Repositories;
using NetCalendy.Domain.Tenants;
using NetCalendy.Domain.Users;

namespace NetCalendy.Application.EventTypes.Commands.CreateEventType;

public sealed class CreateEventTypeHandler(
    IEventTypeRepository eventTypes,
    ICurrentUserService currentUser,
    ICurrentTenantService currentTenant,
    IUnitOfWork uow)
    : IRequestHandler<CreateEventTypeCommand, Result<CreateEventTypeResponse>>
{
    public async Task<Result<CreateEventTypeResponse>> Handle(CreateEventTypeCommand cmd, CancellationToken ct)
    {
        var tenantId = TenantId.From(currentTenant.TenantId!.Value);
        var userId = UserId.From(currentUser.UserId!.Value);

        if (await eventTypes.SlugExistsForUserAsync(cmd.Slug, userId, tenantId, ct))
            return Result.Failure<CreateEventTypeResponse>(
                Error.Conflict("EventType.SlugTaken", $"You already have an event type with slug '{cmd.Slug}'."));

        var result = EventType.Create(tenantId, userId, cmd.Name, cmd.Slug, cmd.DurationMinutes, cmd.Description, cmd.Color);
        if (result.IsFailure) return Result.Failure<CreateEventTypeResponse>(result.Error);

        eventTypes.Add(result.Value);
        await uow.SaveChangesAsync(ct);

        var et = result.Value;
        return Result.Success(new CreateEventTypeResponse(et.Id.Value, et.Name, et.Slug, et.Duration.Minutes, et.Color));
    }
}

using Microsoft.AspNetCore.Mvc;
using NetCalendy.Domain.Common;

namespace NetCalendy.Api.Extensions;

public static class ResultExtensions
{
    public static IActionResult ToActionResult(this Result result) =>
        result.IsSuccess
            ? new OkResult()
            : result.Error.ToActionResult();

    public static IActionResult ToActionResult<T>(this Result<T> result) =>
        result.IsSuccess
            ? new OkObjectResult(result.Value)
            : result.Error.ToActionResult();

    public static IActionResult ToCreatedResult<T>(this Result<T> result, string routeName, object routeValues) =>
        result.IsSuccess
            ? new CreatedAtRouteResult(routeName, routeValues, result.Value)
            : result.Error.ToActionResult();

    private static IActionResult ToActionResult(this Error error)
    {
        var status = error.Code switch
        {
            _ when error.Code.EndsWith(".NotFound") => 404,
            _ when error.Code.Contains(".Conflict") || error.Code.Contains("Taken") || error.Code.Contains("AlreadyCancelled") => 409,
            _ when error.Code.Contains("Forbidden") => 403,
            _ => 400,
        };

        return new ObjectResult(new ProblemDetails
        {
            Title = error.Code,
            Detail = error.Description,
            Status = status,
        })
        { StatusCode = status };
    }
}

// BootQuest kata module: a TESTABLE, self-contained adaptation (not a repo file) of netcalendy @ 99c2710:
//   src/NetCalendy.Application/EventTypes/Commands/CreateEventType/CreateEventTypeHandler.cs (the slug check),
//   src/NetCalendy.Domain/Common/Error.cs (Error + the Conflict factory) and
//   src/NetCalendy.Api/Extensions/ResultExtensions.cs:25-31 (the error-code -> HTTP status switch).
// MediatR, the repositories, the unit of work and the ASP.NET result types are replaced by plain members
// so the flow compiles on its own; the error code, the factory and the status switch are copied verbatim.
namespace NetCalendy.Kata;

public record Error(string Code, string Description)
{
    public static Error NotFound(string entity, object id) =>
        new($"{entity}.NotFound", $"{entity} with id '{id}' was not found.");

    public static Error Conflict(string code, string description) =>
        new(code, description);
}

public sealed record Result(bool IsSuccess, Error? Error)
{
    public bool IsFailure => !IsSuccess;
}

/// <summary>CreateEventTypeHandler.Handle, reduced to the duplicate-slug decision.</summary>
public sealed class CreateEventTypeHandler(Func<string, bool> slugExistsForUser)
{
    public Result Handle(string slug)
    {
        if (slugExistsForUser(slug))
            return new Result(false,
                Error.Conflict("EventType.SlugTaken", $"You already have an event type with slug '{slug}'."));

        return new Result(true, null);
    }
}

/// <summary>ResultExtensions.ToActionResult(Error): the status the API answers with.</summary>
public static class ResultExtensions
{
    public static int StatusFor(Error error)
    {
        var status = error.Code switch
        {
            _ when error.Code.EndsWith(".NotFound") => 404,
            _ when error.Code.Contains(".Conflict") || error.Code.Contains("Taken") || error.Code.Contains("AlreadyCancelled") => 409,
            _ when error.Code.Contains("Forbidden") => 403,
            _ => 400,
        };

        return status;
    }
}

